Script:
if (!(Get-Module -ListAvailable -Name Az.Resources)) {
  Install-Module -Name Az.Resources -Repository PSGallery -AllowClobber -Force -Scope CurrentUser
}
if (!(Get-Module -ListAvailable -Name Az.Accounts)) {
  Install-Module -Name Az.Accounts -Repository PSGallery -AllowClobber -Force -Scope CurrentUser
} 
if (!(Get-Module -ListAvailable -Name Az.Websites)) {
  Install-Module -Name Az.Websites -Repository PSGallery -AllowClobber -Force -Scope CurrentUser
} 

Import-Module Az.Accounts
Import-Module Az.Resources
Import-Module Az.Websites
Import-Module PackageManagement -MinimumVersion 1.4

Write-Host "Welcome to Azure Web App deploy step template!"

$packagesRoot = $Jaws.PackageFolder
$workFolder = $pwd
$packageId = $Jaws.Parameters["STEP.PackageDetails.Package.PackageId"].Value
$packageVersion = $Jaws.Packages[$packageId].PackageVersion
$packageType = $Jaws.Packages[$packageId].PackageType
$packageFileName = $Jaws.Packages[$packageId].FileName
$packageDestination = $workFolder

$AzTenantId = $Jaws.Parameters["CONTEXT.CloudTargetConfig"].ValueAsMap()["TenantID"].Value
$AzSubscriptionId = $Jaws.Parameters["CONTEXT.CloudTargetConfig"].ValueAsMap()["SubscriptionID"].Value
$AzApplicationId = $Jaws.Parameters["CONTEXT.CloudTargetConfig"].ValueAsMap()["ApplicationID"].Value
$AzApplicationPassword = $Jaws.Parameters["CONTEXT.CloudTargetConfig"].ValueAsMap()["ApplicationPassword"].Value

if ([string]::IsNullOrWhiteSpace($AzTenantId)) {
  throw "Required parameter CONTEXT.CloudTargetConfig.TenantID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationId)) {
  throw "Required parameter CONTEXT.CloudTargetConfig.ApplicationID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationPassword)) {
  throw "Required parameter CONTEXT.CloudTargetConfig.ApplicationPassword not specified"
}

$AZWebAappId = $Jaws.Parameters["CONTEXT.CloudTargetConfig"].ValueAsMap()["AzureWebAppId"].Value #required
if ([string]::IsNullOrWhiteSpace($AZWebAappId)) {
  throw "Required parameter CONTEXT.CloudTargetConfig.AzureWebAppId not specified"
}
$AZWebAappSlot = $Jaws.Parameters["STEP.PackageDetails.DeploymentSlot"].Value # optional
$AZWebAappSlotInfo = ""
if (![string]::IsNullOrWhiteSpace($AZWebAappSlot)) {
    $AZWebAappSlotInfo = " slot '$AZWebAappSlot'"
}

# note: "$packageId.$packageVersion" is default NuGet Install-Package convention
$packageContents = Join-Path $packageDestination "$packageId.$packageVersion"

if (-not (Test-Path $packageContents)) {
  New-Item $packageContents -ItemType Directory
}

Switch ($packageType) {
  "nupkg" {
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $packagesRoot to $packageDestination using Install-Package cmdlet"
    $possibleNupkgToRemove = Join-Path $packageContents "$packageId.$packageVersion.nupkg"
    $existed = Test-Path $possibleNupkgToRemove
    Install-Package -Name $packageId -RequiredVersion $packageVersion -Source $packagesRoot -Destination $packageDestination
    Write-Host "Package $packageId @ $packageVersion installed to $packageDestination"
    if (-not $existed -and (test-path $possibleNupkgToRemove)) {
      Write-Host "Removing $possibleNupkgToRemove after nupkg installation with Install-Package"
      Remove-Item $possibleNupkgToRemove
    }
  }

  "zip" {
    $sourceZip = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzipping package $packageId @ $packageVersion of type $packageType from $sourceZip to $packageContents using Expand-Archive cmdlet"
    Expand-Archive $sourceZip $packageContents
    Write-Host "Package $packageId @ $packageVersion unzipped to $packageContents"
  }

  "tar" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvf $sourceTar -C $packageContents
    Write-Host "Package $packageId @ $packageVersion un-tarred to $packageContents"
  }

  "tar.gz" {
    $sourceTar = Join-Path $packagesRoot $packageFileName
    Write-Host "Unzip and un-tar package $packageId @ $packageVersion of type $packageType from $sourceTar to $packageContents using tar.exe"
    tar xvfz $sourceTar -C $packageContents
    Write-Host "Package $packageId @ $packageVersion unzipped and un-tarred to $packageContents"
  }
}

Write-Host "Package files are ready for transformations at $packageContents"



# config transform
$transforms = $Jaws.Parameters["STEP.Transformations.ConfigTransforms"].Value
if ([string]::IsNullOrWhiteSpace($transforms) -eq $false) {
  Write-Host "Executing config transformations"
  @($transforms -Split "`n").Trim() | ForEach-Object {
    $transform = $_
    if ([string]::IsNullOrWhiteSpace($transform) -eq $false) {
      Write-Host "Processing config transformation $transform"
      $idx = $transform.IndexOf(':')
      if ($idx -lt 0) {
        throw "Transformation $transform is invalid"
      }
      $type = $transform.Substring(0, $idx).Trim().ToLowerInvariant()
      $data = $transform.Substring($idx + 1).Split("=>")
      $fileIn = Join-Path $packageContents $data[0].Trim()
      $fileOut = Join-Path $packageContents $data[1].Trim()
      switch ($type) {
        "xml" {
          Convert-JawsXmlTransform -xml $fileOut -xdt $fileIn
        }
        "json" {
          Convert-JawsJsonTransform -json $fileOut -jsonTransform $fileIn
        }
        Default {
          throw "Transformation $type is not supported"
        }
      }
    }
  }
}
else {
  Write-Host "No config transformations defined"
}



# variable replacement
$files = $Jaws.Parameters["STEP.Transformations.VariableReplacement"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "Variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "Variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "Variable replacement - done $_"
    }    
  }
}
else {
  Write-Host "No files for variable replacement defined"
}

# hierarchical variable replacement
$files = $Jaws.Parameters["STEP.Transformations.JsonHierarchyVariableLocateAndReplace"].Value
if ([string]::IsNullOrWhiteSpace($files) -eq $false) {
  Write-Host "JSON hierarchical variable replacement - starting"
  @($files -Split "`n").Trim() | ForEach-Object {
    if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
      Write-Host "JSON hierarchical variable replacement - processing $_"
      $absoluteFilePath = Join-Path $packageContents $_
      Convert-JawsJsonHierarchicalVariableReplace -sourcePath $absoluteFilePath -variables $Jaws.Parameters
      Write-Host "JSON hierarchical variable replacement - done $_"
    }
  }
}
else {
  Write-Host "No files for variable replacement defined"
}

Write-Host "Preparing for Azure deployment"

$packageContentsWildcard = Join-Path $packageContents "*"
$rezippedPackage = Join-Path $packageDestination "$packageId.$packageVersion.zip"
Write-Host "Re-zipping binaries into $rezippedPackage"
Compress-Archive -Path $packageContentsWildcard -DestinationPath $rezippedPackage -Force

Write-Host "Logging in to Azure Account"

Set-JawsAzLogin -TenantId $AzTenantId -ApplicationId $AzApplicationId -Password $AzApplicationPassword -SubscriptionId $AzSubscriptionId

Write-Host "Preparing for Azure deployment"

$AZWebAppInstance = Get-AzResource -ResourceId $AZWebAappId
if (!$AZWebAppInstance) {
  Write-Error "Azure Web App $AZWebAappId not found"
  exit 1
}

$AZWebAppResourceGroup = $AZWebAppInstance.ResourceGroupName
$AZWebAppName = $AZWebAppInstance.Name

Write-Host "Deploying files to Azure Web App '$AZWebAppName'$AZWebAappSlotInfo"

$publishParameters = @{
  ResourceGroupName = $AZWebAppResourceGroup
  Name = $AZWebAppName
  ArchivePath = $rezippedPackage
}

if ($AZWebAappSlot) {
    $publishParameters.Slot = $AZWebAappSlot
}
Publish-AzWebApp @publishParameters -Force

Write-Host "Files deployed"

$AZAppSettings = $Jaws.Parameters["STEP.WebAppConfiguration.AzureAppSettings"].Value
$AZConnectionStrings = $Jaws.Parameters["STEP.WebAppConfiguration.AzureConnectionString"].Value

$moreSettings = @{}

try {
    if ($AZAppSettings) {
        $AZAppSettingsConverted = @{}
        foreach ($prop in (ConvertFrom-Json $AZAppSettings).PSObject.Properties) {
            $AZAppSettingsConverted[$prop.Name] = $prop.Value
        }
        $moreSettings.Add("AppSettings", $AZAppSettingsConverted)
        Write-Host "Updating $($AZAppSettingsConverted.Count) app settings"
    }
} catch {
    Write-Error "Invalid app settings JSON."
    exit 1
}

try {
    if ($AZConnectionStrings) {
        $AZConnectionStringsConverted = @{}
        foreach ($prop in (ConvertFrom-Json $AZConnectionStrings).PSObject.Properties) {
          $AZConnectionStringsConverted[$prop.Name] = @{
            Type = $prop.Value.Type
            Value = $prop.Value.Value
          }
        }
        $moreSettings.Add("ConnectionStrings", $AZConnectionStringsConverted)
        Write-Host "Updating $($AZConnectionStringsConverted.Count) connections strings"
    }
} catch {
    Write-Error "Invalid connection strings JSON."
    exit 1
}

if ($moreSettings.Count -gt 0) {
    $moreSettings.Add("ResourceGroupName", $AZWebAppResourceGroup)
    $moreSettings.Add("Name", $AZWebAppName)
    if ($AZWebAappSlot) {
        $moreSettings.Add("Slot", $AZWebAappSlot)
        Set-AzWebAppSlot @moreSettings
    } else {
        Set-AzWebApp @moreSettings
    }
    Write-Host "Application configured"
}

Write-Host "Azure Web App deployment complete"

Remove-JawsAzLogin

Write-Host "Logged off from Azure"
